def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    def dominant_line(values):
        counts = Counter(values)
        value, count = counts.most_common(1)[0]
        return value, count / len(values)

    # Grid separators are the regularly recurring rows and columns whose
    # dominant color differs from the interior/background color.
    row_lines = []
    for r in range(h):
        v, frac = dominant_line(grid[r])
        if v != bg and frac >= 0.65:
            row_lines.append(r)

    col_lines = []
    for c in range(w):
        v, frac = dominant_line([grid[r][c] for r in range(h)])
        if v != bg and frac >= 0.65:
            col_lines.append(c)

    if len(row_lines) < 2 or len(col_lines) < 2:
        return grid

    row_sep = Counter(dominant_line(grid[r])[0] for r in row_lines).most_common(1)[0][0]
    col_sep = Counter(dominant_line([grid[r][c] for r in range(h)])[0]
                      for c in col_lines).most_common(1)[0][0]

    # Use the marked intersections to locate the section of the lattice.
    marked = []
    for i, r in enumerate(row_lines):
        for j, c in enumerate(col_lines):
            v = grid[r][c]
            if v != bg and v != row_sep and v != col_sep:
                marked.append((i, j))

    if not marked:
        return [[bg]]

    r0 = min(i for i, _ in marked)
    r1 = max(i for i, _ in marked)
    c0 = min(j for _, j in marked)
    c1 = max(j for _, j in marked)

    out = []
    for i in range(r0, r1):
        row = []
        for j in range(c0, c1):
            corners = [
                grid[row_lines[i]][col_lines[j]],
                grid[row_lines[i]][col_lines[j + 1]],
                grid[row_lines[i + 1]][col_lines[j]],
                grid[row_lines[i + 1]][col_lines[j + 1]],
            ]
            v = corners[0]
            if all(x == v for x in corners) and v not in (row_sep, col_sep):
                row.append(v)
            else:
                row.append(bg)
        out.append(row)
    return out
